promptPassword(
  aDialogTitle,
  aText,
  aPasswordRealm,
  aSavePassword,
  aPassword
) {
  let finished = false;
  let result = false;
  this.#promptPasswordInternal(
    aDialogTitle,
    aText,
    aPasswordRealm,
    aSavePassword,
    aPassword
  )
    .then(ok => (result = ok))
    .finally(() => (finished = true));
  Services.tm.spinEventLoopUntilOrQuit(
    "MsgAuthPrompt:promptPassword",
    () => finished
  );
  return result;
}
